'use strict';
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const root=path.resolve(__dirname,'..'),out=path.join(root,'outputs/youth-comparison-20years-20261011'),s=JSON.parse(fs.readFileSync(path.join(out,'summary.json'),'utf8'));
assert(s.complete&&s.latest===20,'Only completed results may be published');
const n=(x,d=1)=>x==null?'–':new Intl.NumberFormat('de-DE',{minimumFractionDigits:d,maximumFractionDigits:d}).format(Math.abs(x)<.5*10**(-d)?0:x),pct=x=>(x>0?'+':'')+n(x)+' %';
const final=s.variants.map(v=>({v,r:v.series.at(-1)})),color=x=>['Sehr schwach','Schwach','Normal','Gut','Sehr gut'][Math.min(4,Math.floor(x/20))];
const lines=['# Jugendstatus und Länderrahmen: Vergleich über 20 Saisons','',`Drei Varianten mit denselben drei Seeds **youth20-a/b/c** und jeweils 20 nativen Saisons. ${n(s.newFixtures,0)} neue Partien plus ${n(s.totalFixtures-s.newFixtures,0)} bereits ausgewertete Karriereend-Partien: insgesamt **${n(s.totalFixtures,0)}**. 95 KI-Ligavereine pro Welt; AUT-5 folgt in allen Läufen derselben minimalen Managerpolitik und ist aus Vereinsmittelwerten ausgeschlossen. Kein Produktcode, reale Spielstände oder Live-Seite geändert.`,'','## Ergebnis nach Saison 20','','| Kennzahl | Karriereenden | + Jugendstatus | + Länderrahmen |','| --- | ---: | ---: | ---: |'];
const metrics=[['Stärke Standardstartformation gegenüber Anfang','startingPct',pct],['Kaderstärke vor Karriereenden gegenüber Anfang','playingPct',pct],['Kaderstärke nach Karriereenden gegenüber Anfang','qualityPct',pct],['Spieler zu Saisonbeginn / Verein','openingPlayers',x=>n(x,2)],['Spieler nach Abschluss / Verein','closingPlayers',x=>n(x,2)],['Durchschnittsalter nach Abschluss','meanAge',x=>n(x,1)],['Jahresausgaben / Verein, Credits','expenses',x=>n(x,0)],['Davon Förderung / Verein','youthFunding',x=>n(x,0)],['Jahreseinnahmen / Verein','income',x=>n(x,0)],['Guthaben nach Abschluss / Verein','balance',x=>n(x,0)],['Jugendanteil am Kader nach Abschluss','youthRosterSharePct',x=>n(x)+' %'],['Jugendanteil an echten Spielminuten aller Wettbewerbe','youthMinutesPct',x=>n(x)+' %']];
for(const [label,key,f]of metrics)lines.push(`| ${label} | ${final.map(({r})=>f(r[key])).join(' | ')} |`);
lines.push(`| Neue Kandidaten insgesamt pro Welt in 20 Saisons | ${final.map(({v})=>n(v.totals.generated,0)).join(' | ')} |`,`| Übernahmen insgesamt pro Welt in 20 Saisons | ${final.map(({v})=>n(v.totals.promoted,0)).join(' | ')} |`,`| A-Länder gegenüber D-Ländern, mittlere Kaderstärke | ${final.map(({v})=>pct(v.tierSeries.at(-1).aRelativeToDPct)).join(' | ')} |`,'','Die Startformation wird unmittelbar vor den Karriereenden mit der gleichen Standardformation gemessen. Das ist kein Mittel der tatsächlich taktisch gewählten Aufstellungen. Der volle Kader wird zusätzlich vor und nach den Abgängen gemessen: Ausscheiden schwacher älterer Spieler kann den Kaderdurchschnitt erhöhen, ohne den Wettbewerbskader entsprechend zu verbessern. Die Jugend-Minutenquote umfasst auch reine Pokalvereine; sie ist keine ausschließlich auf die Liga bezogene Quote.','', '## Getrennte Effekte und Zufallsstreuung','','| Vergleich | Startformation: Differenz in Prozentpunkten | Kader: Differenz in Prozentpunkten | Zusätzliche Jahresausgaben S20 / Verein | Jahrgangsqualität S20 relativ zur vorherigen Variante |','| --- | ---: | ---: | ---: | ---: |');
for(const d of s.differences)lines.push(`| ${d.variant==='status'?'Förderpaket gegenüber Karriereenden':'Länderrahmen zusätzlich zum Förderpaket'} | ${n(d.meanStartingPctPoints,2)} | ${n(d.meanQualityPctPoints,2)} | ${n(d.meanExpenses,0)} | ${pct(d.meanBirthQualityPct)} |`);
lines.push('','Das Förderpaket verändert **gemeinsam** vier Budgetstufen, die Kandidatenmenge, den dynamischen Status und die Startqualität. Seine Differenz isoliert daher nicht die reine Statuswirkung. Der zweite Vergleich isoliert den zusätzlichen Länderrahmen, weil die übrigen Parameter gleich bleiben.','', '| Seed | Förderpaket: Startformations-Differenz | Länderrahmen: zusätzliche Startformations-Differenz |','| --- | ---: | ---: |');
for(let i=0;i<3;i++)lines.push(`| ${s.differences[0].matchedSeeds[i].seed} | ${n(s.differences[0].matchedSeeds[i].startingPctPoints,2)} Prozentpunkte | ${n(s.differences[1].matchedSeeds[i].startingPctPoints,2)} Prozentpunkte |`);
lines.push('','### Stabilität in den letzten fünf Saisons','','Mittel aus S16–20, um den einzelnen Schlussjahrgang zu ergänzen.','', '| Variante | Startformation gegenüber Anfang | Kader gegenüber Anfang | Jahresausgaben / Verein | A gegenüber D |','| --- | ---: | ---: | ---: | ---: |');
for(const v of s.variants)lines.push(`| ${v.label} | ${pct(v.lastFive.startingPct)} | ${pct(v.lastFive.qualityPct)} | ${n(v.lastFive.expenses,0)} | ${pct(v.lastFive.countryGapPct)} |`);
lines.push('','### Verbleib der Anfangsspieler','','| Variante / Seed | Ursprüngliche Erwachsene noch aktiv | Damals übernommene Jugendliche noch aktiv | Höchstes aktives Alter | Negative Guthaben in Vereinsjahren |','| --- | ---: | ---: | ---: | ---: |');
for(const v of s.validation)for(const r of v.seeds)lines.push(`| ${s.variants.find(x=>x.id===v.variant).label} / ${r.seed} | ${r.originalAdultsRemaining} | ${r.initialRemaining-r.originalAdultsRemaining} | ${r.maximumActiveAge} | ${r.negativeBalanceClubYears} |`);
lines.push('','Alle ursprünglichen erwachsenen Spieler sind in allen neun Läufen ausgeschieden. Wenige bereits beim Start übernommene 17-Jährige bleiben mit 36 aktiv. Die Staffel garantiert das Ausscheiden bis 39, keinen pauschalen Stichtag nach 20 Saisons für jede Anfangsaltersgruppe.');
lines.push('','Drei Seeds sind ein Balancetest mit sichtbarer Streuung, kein präziser Nachweis für jede Karriere. Ergebnisse beziehen sich auf die native kompakte Spielsimulation; daraus folgt keine neue Abnahme von WebGL, mobilen Oberflächen oder physischen Echtzeitpartien.','', '## Alle Jahreswerte','','Stärke relativ zum identischen Anfangskader; Kosten als Bruttoausgaben pro KI-Verein. Kandidaten und Übernahmen als Mittel der Weltsummen, einschließlich späterer Übernahmen älterer Pooljahrgänge. Erste Y0-Kandidaten zählen nicht als neu generiert, ihre Übernahmen können enthalten sein. Die jährliche Division von Übernahmen durch Kandidaten ist deshalb keine Jahrgangs-Aufnahmequote.');
for(const v of s.variants){lines.push('',`### ${v.label}`,'','| Saison | Startformation | Kader nach Abschluss | Spieler Beginn / Ende | Ausgaben / Verein | Neu generiert / Welt | Übernommen / Welt |','| ---: | ---: | ---: | ---: | ---: | ---: | ---: |');for(const r of v.series)lines.push(`| ${r.season} | ${pct(r.startingPct)} | ${pct(r.qualityPct)} | ${n(r.openingPlayers,2)} / ${n(r.closingPlayers,2)} | ${n(r.expenses,0)} | ${n(r.generated,1)} | ${n(r.promoted,1)} |`);}
lines.push('','## Länder nach 20 Saisons','','Jede Landesentwicklung ist relativ zum eigenen Startkader. Sie sagt allein noch nicht, welches Land absolut stärker ist. Der direkte A/D-Abstand oben vergleicht die durchschnittliche absolute Kaderqualität derselben Phase.','', '| Land | Karriereenden | + Jugendstatus | + Länderrahmen |','| --- | ---: | ---: | ---: |');
for(const c of s.variants[0].countries)lines.push(`| ${c.label} | ${s.variants.map(v=>pct(v.countries.find(x=>x.country===c.country).series.at(-1).qualityPct)).join(' | ')} |`);
lines.push('','## Förderstufen und gewachsener Status','','Die folgenden beobachteten Gruppen sind **kein kausaler Budgetvergleich**: Vereinsprofile, Reserven, Erfolge und Historien unterscheiden sich. Die Stufe beschreibt das jeweilige bezahlte Budget; die Menge hängt von der dreijährigen Glättung ab. Vereinsjahre umfassen S2–20, die sichtbare Statusbewertung den Abschluss von S20.','', '| Variante / Budget | Vereinsjahre | Kandidaten / Jahr | Übernahmen / Jahr | Ausgaben / Jahr | Status nach S20 (Gruppenmittel) |','| --- | ---: | ---: | ---: | ---: | --- |');
for(const f of s.funding)lines.push(`| ${f.variant==='status'?'Status':'Status + Land'} / ${n(f.budget,0)} | ${n(f.clubYears,0)} | ${n(f.meanGenerated,2)} | ${n(f.meanPromoted,2)} | ${n(f.meanExpenses,0)} | ${f.meanFinalStatus==null?'–':color(f.meanFinalStatus)} (${n(f.finalClubSamples,0)} Vereine in drei Welten) |`);
lines.push('','Die KI zahlt 0 hier nur vorübergehend wegen fehlender Reserven; am Ende verwendet keiner der 95 KI-Vereine je Welt dauerhaft die Nullstufe. Dauerhafte Nullförderung wird deshalb nur durch die getrennten Status- und Generierungsrechner geprüft, nicht durch eine eigene 20-jährige Pflichtspielkarriere.','', '## Positionsmix: ein weiterer Generierungsbefund','','60 getrennte Jahrgänge je konstant geglätteter Förderstufe mit derselben nativen Positionsfolge; keine zusätzlichen gespielten Karrieren.','', '| Stufe | Torhüter | Abwehr | Mittelfeld | Angriff |','| --- | ---: | ---: | ---: | ---: |');
const positions=JSON.parse(fs.readFileSync(path.join(out,'position-controls.json'),'utf8'));
for(const r of positions.rows)lines.push(`| ${n(r.budget,0)} | ${r.positions.gk} | ${r.positions.def} | ${r.positions.mid} | ${r.positions.att} |`);
lines.push('','Die bisherige Slotfolge koppelt Position und Kandidatenmenge: Bei dauerhaft 0 werden **keine Stürmer** erzeugt. Ab 500 gibt es immer einen Stürmer pro Jahr und unabhängig von der Förderung einen Torhüter je drei Jahre. Der sechste Kandidat bei 1.500 ist immer ein Verteidiger. Damit erhöht höhere Förderung die Auswahl nicht für jede Position. Für die Umsetzung sollten Jahr/Seed die Positionen variieren und jede Förderstufe grundsätzlich alle Positionen hervorbringen können.');
lines.push('','## Direkte Wirkung der sportlichen Legacy','','Kontrollrechnung auf den aufgezeichneten Förderverläufen: tatsächlicher Sportwert gegenüber konstant erwartungsgemäßem Erfolg. Budgets, Kandidatenmengen und Saisonverläufe bleiben für diese Rechnung fest; sie simuliert keine neuen Spielergebnisse oder Finanzrückwirkungen. Geprüft wird, ob der Sportanteil allein die Qualitätsfarbe vor der Erzeugung verändert.','', '| Variante | Vereinsjahre mit anderem Qualitätsfaktor | Anteil an S2–20 | Kandidatengewichtete direkte Qualitätswirkung | Unterschiedliche Statusfarben nach S20 |','| --- | ---: | ---: | ---: | ---: |');
for(const x of s.legacy)lines.push(`| ${s.variants.find(v=>v.id===x.variant).label} | ${x.changedGenerationBands} / ${x.clubYears} | ${n(x.changedGenerationBandsPct,2)} % | ${pct(x.qualityFactorEffectPct)} | ${x.finalClubsWithDifferentColor} / ${x.finalClubSamples} |`);
lines.push('','Kleine Statusänderungen innerhalb derselben Farbe verändern in diesem Versuch den Qualitätsfaktor nicht. Diese Quantisierung kann die sportliche Legacy trotz ihres nominellen 35-Prozent-Gewichts abschwächen. Eine stufenlose interne Qualitätswirkung bei weiterhin fünf sichtbaren Farben ist ein möglicher nächster Test.');
lines.push('','Die Farbe eines Gruppenmittels ist nur eine Übersicht. Die tatsächlichen fünf Farbverteilungen je Budget sind in summary.json gespeichert; ein Durchschnitt ersetzt keine einzelne Vereinsbewertung. Interne Statuspunkte und einzelne Spielerwerte werden nicht als Produktwerte gezeigt.','', '## Entwicklung über Profieinsätze','','| Variante | Beobachtete Spieler bis Alter 24 | Mittlere relative Fähigkeitsentwicklung seit Erzeugung | Tatsächliche Minuten bis Alter 24 |','| --- | ---: | ---: | ---: |');
for(const v of s.finalYouth24)lines.push(`| ${s.variants.find(x=>x.id===v.variant).label} | ${n(v.sample,0)} | ${pct(v.growthPct)} | ${n(v.minutes,0)} |`);
lines.push('','Nur ab S2 erzeugte und tatsächlich bis zum Eintritt in Alter 24 beobachtete Jugendliche mit Alters-/Entwicklungsledger; ausgeschiedene Kandidaten ohne diesen Messpunkt fehlen. Daher Überlebenden-Auswahl, kein Durchschnitt aller generierten Jugendlichen. Poolaufenthalt allein entwickelt weiterhin keine Fähigkeiten. Die Entwicklung erfolgt über reale bewertete Einsätze.','', '## Exakte Testparameter und Grenzen','', '- **Karriereenden:** Alter 33: 40 %, danach jährlich +10 Prozentpunkte; einmal deterministisch in der Mitte des 224-Tage-Kalenders, Ausführung zum Saisonabschluss. Gleiche Regel und Zufallskennungen in allen drei Varianten.','- **Identischer Start:** Native Konstruktion einschließlich Startkader, Y0-Pools, ursprünglicher erster KI-Finanzierung und automatischer Übernahmen bleibt unverändert. Auch neu entdeckte Jugendliche des betreuten Vereins werden in S1 unverändert erzeugt. Der Jugendstatus wird erstmals nach S1 aktualisiert; neue vierstufige KI-Förderung und Jugendqualität greifen ab S2. Neue Pokalersatzspieler im Abschluss gehören bereits zum Folgejahr.','- **Budgets:** Nur 0/500/1.000/1.500 bei KI-Ligavereinen ab S2. Gewünschte Stufe nach altem Jugendprofil 1–5: 0/500/1.000/1.000/1.500. Volle Vertragsgehälter plus 450 Reserve sichern; höchstens 22 % des verbleibenden Guthabens verwenden. Größte gedeckte Stufe bis zur gewünschten Höhe wählen. Der betreute Kontrollverein behält seine ursprüngliche höchstens 200-Credits-Politik.','- **Mengen:** Bei stabil bezahltem Budget Mittelwerte 1,5/3,5/5/6 neue Kandidaten; maximal sechs. Menge wird anhand geglätteter Förderung interpoliert und mit derselben ID-basierten Zufallsziehung auf ganze Spieler gebracht.','- **Status:** Startwerte nach bisherigen Jugendprofilen 10/30/50/70/90; 65 % Förderziel plus 35 % sportlicher Erfolg. Förderziele für die vier Budgets 0/45/75/100, Budgethistorie 45/35/20 %. Annäherung an bessere Ziele jährlich 15 % des Abstands, an schlechtere 5 %.','- **Sport:** Vor Pflichtspielbeginn nach Transferabschluss Rang-Erwartung anhand nativer Kaderqualität einfrieren. Basis 50; tatsächliche Rangabweichung bis ±25. Weitere maximal 25: Meistertitel 5, nationaler Pokal bis 5, Crown bis 15 beziehungsweise Horizon bis 10. Je Pokal nur höchste erreichte Stufe: Teilnahme 5 %, R16 15 %, QF 30 %, SF 50 %, Finale 70 %, Titel 100 % des Wettbewerbsbeitrags. Teilnahme setzt ein wirklich gespieltes Ergebnis voraus. Diese konkrete Punktverteilung ist ein Testvorschlag; in diesem Modell ist 25 das niedrigste erreichbare sportliche Jahresergebnis.','- **Jahrgangsqualität:** Normaler nativer Jugend-Qualitätsrahmen als gemeinsame Basis; je Statusfarbe −6/−3/0/+3/+6 % auf die Zielverteilung. Der alte Jugendprofil-Qualitätsrahmen wird ersetzt, nicht nochmals aufaddiert. Kappung und Fähigkeitsobergrenzen bleiben im nativen Generator. Bestehende Spieler werden nicht geändert.','- **Talent:** Alte statische Jugendprofile und deren normalisierte Bevölkerungsgewichte bleiben erhalten. Status verändert hier die Startfähigkeiten, nicht die profilbezogenen Talentziehungen. Andere Kandidatenmengen verändern aber den Profilmix und können damit die tatsächlichen globalen Talentanteile verschieben. Eine erneute globale Normalisierung und dynamische Umgewichtung hoher Talente wäre ein eigener Test und ist nicht enthalten.','- **Länderrahmen:** Feste bestehende Landesgruppen A +3 %, B +1 %, C 0 %, D −2 % beim Erzeugungsland für neue Jugendliche, freie Spieler und neue Pokalersatzspieler. Bei Pokalersatzspielern wird der vorhandene additive Länderanteil entfernt, der Vereinsanteil bleibt; kein doppelter Länderbonus. Jugend- und Länderanteil addieren sich in der Zielverteilung. Nationalität und Transfer verändern bereits erzeugte Fähigkeiten nicht.','- **Auswahl/Entwicklung:** Native KI-Auswahl, Vertrags-/Transferlogik, Einsatzentwicklung, Alterung und Kostenbuchungen unverändert. Insbesondere keine zusätzliche Auswertung geheimer Talente oder Obergrenzen in der KI; die veraltete Potenziallesung bleibt für diesen Paketvergleich unverändert. Keine Akademietrainings-, Vorauswahl-/Scouting- oder UI-Implementierung.','','## Prüfnachweise','', '- Alle sechs neuen Welten vollständig bis S20; 991 native Ergebnisse je Saison; vollständige native Karrierevalidatoren nach S1, S10 und S20.','- Erste 991 Ergebnisse jedes neuen Laufs identisch zur zugehörigen Karriereend-Basis; Anfangs- und erste Saison-Ligakader unverändert.','- Sämtliche 143 eingefrorenen Quellen und die vier Instrumentierungsskripte über Hashes geprüft; während des endgültigen Laufs keine Regeländerung.','- Jahresausgaben in Gehälter, Förderung, Übernahmeentschädigungen und Transfers zerlegt; tatsächliche Transfersummen und Karriereereignisse abgeglichen. Der alte Roh-Beobachter erkennt nicht jede Transferbuchung am Label; die veröffentlichten Transferkosten werden deshalb aus den vollständigen Transferereignissen rekonstruiert und gegen die Gesamtausgaben geprüft. Aufnahmen, Altersentscheidungen und aktive Spielerherkunft geprüft.','- 2.400 reine Jugend-Generierungsfälle: Qualitätsfaktoren, native Talentgleichheit und gültige Fähigkeiten/Obergrenzen; zusätzlich 640 freie-/Pokal-Generierungsfälle mit einmaligem Länderrahmen und unveränderten Talent-, Größen- und Fußziehungen. Kontrollrechner für alle vier Budgetstufen, Unter-/Übererfüllung und 20-jährige Statusverläufe.','- Frühe Vorprüfung mit Startjahres-Abweichung ausschließlich unter ../outputs/youth-comparison-20years-20261011-preflight archiviert; diese Teilläufe sind verworfen und gehen nicht in Ergebnisse ein.','', '[Interaktive Übersicht](../outputs/youth-comparison-20years-20261011/report.html) · [Alle Jahreswerte als CSV](../outputs/youth-comparison-20years-20261011/annual.csv) · [Länderwerte als CSV](../outputs/youth-comparison-20years-20261011/countries.csv) · [Zusammenfassung](../outputs/youth-comparison-20years-20261011/summary.json) · [Prüfungen](../outputs/youth-comparison-20years-20261011/validation.json) · [Parameter und Hashes](../outputs/youth-comparison-20years-20261011/experiment-manifest.json)');
lines.splice(4,0,`**Ergebnis:** Das Förderpaket verbessert die Standardstartformation gegenüber Karriereenden allein um ${n(s.differences[0].meanStartingPctPoints,2)} Prozentpunkte und kostet in S20 ${n(s.differences[0].meanExpenses,0)} Credits mehr je Verein. Der zusätzliche Länderrahmen bringt weitere ${n(s.differences[1].meanStartingPctPoints,2)} Prozentpunkte. Die bisherigen Vorschläge funktionieren grundsätzlich, die Qualitätswirkung der sportlichen Legacy bleibt aber sehr klein.`, '');
const recommendations=['## Bewertung und nächste Anpassung','', '- Vier Förderbeträge, Karriereendstaffel und die getestete Statusgeschwindigkeit beibehalten. Das Paket erneuert die Kader ausreichend; zusätzliche Kandidaten allein sind nicht erforderlich.','- **Qualität stufenlos aus dem internen Status ableiten**, während außen weiterhin fünf Farben und der Trendpfeil stehen. Die nominellen 35 % Sport wirken hier in nur rund 5 % der Vereinsjahre auf die Jahrgangsqualität; die kandidatengewichtete direkte Wirkung beträgt nur ungefähr 0,1 %.','- Die Qualitätsverteilungen neu kalibrieren: Der mittlere neue S20-Jahrgang ist mit Status allein noch nicht stärker als in der Karriereend-Basis, obwohl mehr bezahlt wird. Als ungetesteter nächster Kandidat können die fünf Statusmitten −12/−6/0/+6/+12 % gegenüber der normalen Jugendbasis liefern, mit stufenloser Verbindung. Das ersetzt die getesteten −6/−3/0/+3/+6 %, ohne zweiten Qualitätsbonus.','- **Positionen von der festen Slotnummer lösen**: insbesondere Nullförderung muss Stürmer liefern können und 1.500 darf den Zusatzplatz nicht immer für die Abwehr verwenden.','- Den Länderrahmen behalten, aber weiter kalibrieren. S20 liegt A 2,3 % vor D, im Mittel S16–20 nur 1,1 %; das gewünschte dauerhafte 3–5-Prozent-Fenster wird noch nicht erreicht. Ein nächster ungetesteter Kandidat wäre A +4 %, B +2 %, C 0 %, D −3 %.','- 1.500 ist finanziell eine echte Priorität: In beobachteten Jahren dieser Stufe verbleiben durchschnittlich nur rund 70–110 Credits zwischen Bruttoeinnahmen und Ausgaben. Die Gruppe ist durch Reserven und Vereinseigenschaften selektiert; daraus folgt keine Kostenwirkung bei identischen Vereinen. Zusätzliche Sichtungskosten sind noch nicht enthalten.','- Bei einer späteren Umsetzung die globale Talentnormalisierung an die geplanten Kandidatenmengen anpassen und die alte KI-Potenziallesung getrennt korrigieren. Dieser Vergleich übernimmt die alten profilbezogenen Wahrscheinlichkeiten; der veränderte Kandidatenmix kann globale Talentanteile verändern.','', 'Diese Folgekandidaten sind Vorschläge, keine bestätigten Produktparameter und keine Änderungen an laufenden Spielständen.',''];
lines.splice(lines.indexOf('## Alle Jahreswerte'),0,...recommendations);
fs.writeFileSync(path.join(root,'docs/jugendstatus-laender-vergleich-20261011.md'),lines.join('\n')+'\n');
const columns=['startingPct','playingPct','qualityPct','openingPlayers','closingPlayers','meanAge','expenses','salaries','youthFunding','promotionFees','transferFees','income','balance','generated','promoted','retired','youthRosterSharePct','youthMinutesPct'];
const csvLine=(v,r)=>[v.id,r.season,...columns.map(k=>r[k]==null?'':r[k].toFixed(6).replace('.',','))].join(';');
fs.writeFileSync(path.join(out,'annual.csv'),'\ufeffVariante;Saison;'+columns.join(';')+'\n'+s.variants.flatMap(v=>v.series.map(r=>csvLine(v,r))).join('\n')+'\n');
fs.writeFileSync(path.join(out,'countries.csv'),'\ufeffLand;Variante;Saison;'+columns.join(';')+'\n'+s.variants.flatMap(v=>v.countries.flatMap(c=>c.series.map(r=>c.country+';'+csvLine(v,r)))).join('\n')+'\n');
console.log('Wrote completed comparison report and two CSVs');
